public class HandleClaimWaiveRefused {
    public void handle(@Parameter ClaimWaiveRefusedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.UNPROCESSABLE_ENTITY));
